Author: dos
Date: Thu Oct  4 07:58:37 2007
New Revision: 581940

URL: http://svn.apache.org/viewvc?rev=581940&view=rev
Log:
ensure that timestamps are duplicated; duplicate timestamps wipe out the ability to timeout any messages previously sent in the same second, thus preventing mass-check --server from ever completing (it'll wait forever for those messages); this is trivial to trigger by hand and more common to occur naturally the more machines you add to your cluster

Modified:
    spamassassin/trunk/masses/mass-check

Modified: spamassassin/trunk/masses/mass-check
URL: http://svn.apache.org/viewvc/spamassassin/trunk/masses/mass-check?rev=581940&r1=581939&r2=581940&view=diff
==============================================================================
--- spamassassin/trunk/masses/mass-check (original)
+++ spamassassin/trunk/masses/mass-check Thu Oct  4 07:58:37 2007
@@ -162,6 +162,7 @@
 use constant HAS_IO_ZLIB => eval { require IO::Zlib; };
 use constant HAS_IO_SOCKET_SSL => eval { require IO::Socket::SSL; };
 use Config; 
+use constant HAS_TIME_HI_RES => eval { require Time::HiRes; };


 # default settings
@@ -1221,6 +1222,21 @@

   # update timestamp entries
   my $ts = time;
+
+  # make sure the timestamp is unique!  without Time::HiRes it is trivial and
+  # common to have two reissueings of timedout messages in the same second
+  # with Time::HiRes we'll check anyway since we'll waste less time checking
+  # for uniqueness than one of us will waste debugging a report of mass-check
+  # not completing due to someone's wacky clock (some (non-para-)virtualized
+  # servers will have their clocks go forward and backward
+  while (exists $timestamps->{$ts}) {
+    if (HAS_TIME_HI_RES) {
+      $ts = time;
+    } else {
+      $ts += 0.01;
+    }
+  }
+
   foreach (@sent) {
     $msgsout->{$_}->{'timestamp'} = $ts;
   }

# New Ticket Created by  Andy Dougherty 
# Please include the string:  [perl #46111]
# in the subject line of all future correspondence about this issue. 
# 


The following patch adds tests for commands that print only to stderr to 
the IPC::Cmd test suite.

These tests currently fail for me under Solaris 8 with Sun's cc compiler. 
(And this failure ultimately shows up as a failure in Archive::Extract 
when it tries to parse the stderr output of bzip2 --version).


diff -ru perl-current/lib/IPC/Cmd/t/01_IPC-Cmd.t perl-andy/lib/IPC/Cmd/t/01_IPC-Cmd.t
--- perl-current/lib/IPC/Cmd/t/01_IPC-Cmd.t	Tue Nov 28 05:45:22 2006
+++ perl-andy/lib/IPC/Cmd/t/01_IPC-Cmd.t	Fri Oct  5 13:26:32 2007
@@ -35,7 +35,7 @@
     ok( !can_run('10283lkjfdalskfjaf'), q[Not found non-existant binary] );
 }

-### run tests
+### run tests that print only to stdout
 {   ### list of commands and regexes matching output ###
     my $map = [
         # command                                    # output regex
@@ -45,6 +45,7 @@
         [ [$^X,qw[-eprint+42 |], $^X, qw|-neprint|], qr/42/,            ],
     ];

+    diag( "Running tests that print only to stdout" ) if $Verbose;
     ### for each configuarion
     for my $pref ( @Prefs ) {
         diag( "Running config: IPC::Run: $pref->[0] IPC::Open3: $pref->[1]" )
@@ -108,6 +109,79 @@
     }
 }

+### run tests that print only to stderr
+{   ### list of commands and regexes matching output ###
+    my $map = [
+        # command                                    # output regex
+        [ "$^X -ewarn+42",                          qr/^42 /, ],
+        [ [$^X, '-ewarn+42'],                       qr/^42 /, ],
+    ];
+
+    diag( "Running tests that print only to stderr" ) if $Verbose;
+    ### for each configuarion
+    for my $pref ( @Prefs ) {
+        diag( "Running config: IPC::Run: $pref->[0] IPC::Open3: $pref->[1]" )
+            if $Verbose;
+
+        $IPC::Cmd::USE_IPC_RUN    = $IPC::Cmd::USE_IPC_RUN      = $pref->[0];
+        $IPC::Cmd::USE_IPC_OPEN3  = $IPC::Cmd::USE_IPC_OPEN3    = $pref->[1];
+
+        ### for each command
+        for my $aref ( @$map ) {
+            my $cmd                 = $aref->[0];
+            my $regex               = $aref->[1];
+
+            my $pp_cmd = ref $cmd ? "@$cmd" : "$cmd";
+            diag( "Running '$pp_cmd' as " . (ref $cmd ? "ARRAY" : "SCALAR") )
+                if $Verbose;
+
+            ### in scalar mode
+            {   diag( "Running stderr command in scalar mode" ) if $Verbose;
+                my $buffer;
+                my $ok = run( command => $cmd, buffer => \\$buffer );
+
+                ok( $ok,        "Ran stderr command succesfully in scalar mode." );
+
+                SKIP: {
+		    # No buffers are expected if neither IPC::Run nor IPC::Open3 is used.
+                    skip "No buffers available", 1
+                                unless $Class->can_capture_buffer;
+
+                    like( $buffer, $regex,
+                                "   Buffer filled properly from stderr" );
+                }
+            }
+
+            ### in list mode
+            {   diag( "Running stderr command in list mode" ) if $Verbose;
+                my @list = run( command => $cmd );
+                ok( $list[0],   "Ran stderr command successfully in list mode." );
+                ok( !$list[1],  "   No error code set" );
+
+                my $list_length = $Class->can_capture_buffer ? 5 : 2;
+                is( scalar(@list), $list_length,
+                                "   Output list has $list_length entries" );
+
+                SKIP: {
+		    # No buffers are expected if neither IPC::Run nor IPC::Open3 is used.
+                    skip "No buffers available", 6
+                                unless $Class->can_capture_buffer;
+
+                    ### the last 3 entries from the RV, are they array refs?
+                    isa_ok( $list[$_], 'ARRAY' ) for 2..4;
+
+                    like( "@{$list[2]}", $regex,
+                                "   Combined buffer holds output" );
+
+                    is( scalar( @{$list[3]} ), 0,
+                                    "   Stdout buffer empty" );
+                    like( "@{$list[4]}", qr/$regex/,
+                            "   Stderr buffer filled" );
+                }
+            }
+        }
+    }
+}

 ### test failures
 {   ### for each configuarion

-- 
    Andy Dougherty		uloqorhi@lafayette.edu

