Hi,

rgs alerted me to the fact that all patches generated by add-package.pl
include a diff entry for the '.patch' file which the APC adds, but isn't
actually in the repository.

The below patch excludes this file from the diff that is run:

--- Porting/add-package.pl      2007-07-02 15:38:47.000000000 +0200
+++ core-integration/bin/add-package.pl     2007-10-04  
11:17:04.000000000 +0200
@@ -407,14 +407,20 @@
  if( $RunDiff ) {
      my $diff = $Repo; $diff =~ s/$$/patch/;

-    print "Generating diff..." if $Verbose;
-
      ### weird RV ;(
      my $master = basename( $MasterRepo );
      my $repo   = basename( $Repo );
      my $chdir  = dirname( $MasterRepo );

-    system( "cd $chdir; diff -ruN $master $repo > $diff" );
+    ### the .patch file is added by an rsync from the APC
+    ### but isn't actually in the p4 repo, so exclude it
+    my $cmd     = "cd $chdir; diff -ruN --exclude=.patch $master  
$repo > $diff";
+
+    print "Running: '$cmd'\\n";
+
+    print "Generating diff..." if $Verbose;
+
+    system( $cmd );
          #and die "Could not write diff to '$diff': $?";
      die "Could not write diff to '$diff'" unless -e $diff && -s _;


--

   Jos Boumans

